SELECT A.numb1120, A.Year, A.E, B.E, A.EOTP, B.EOTP, A.EURT, B.EURT, A.EUST, B.EUST, A.Q, B.Q, A.TURT, B.TURT, A.TUST, B.TUST, A.B, B.B, A.GAZ, B.GAZ, A.ISK_GAZ, B.ISK_GAZ, A.MAZUT, B.MAZUT, A.TORF, B.TORF, A.SLAN, B.SLAN, A.PROCH, B.PROCH, A.UGOL, B.UGOL, A.DON, B.DON, A.PODM, B.PODM, A.PECH, B.PECH, A.ARKT, B.ARKT, A.KUZN, B.KUZN, A.URAL, B.URAL, A.BASHK, B.BASHK, A.KAZAH, B.KAZAH, A.KAN, B.KAN, A.TUNG, B.TUNG, A.IRKUT, B.IRKUT, A.HAK, B.HAK, A.TUV, B.TUV, A.BUR, B.BUR, A.CHIT, B.CHIT, A.YAKUT, B.YAKUT, A.AMUR, B.AMUR, A.URG, B.URG, A.USHUM, B.USHUM, A.PRIM, B.PRIM, A.MAG, B.MAG, A.CHUKOT, B.CHUKOT, A.KAMCH, B.KAMCH, A.SAH, B.SAH, A.QOTR, B.QOTR, A.SNK, B.SNK, A.SNt, B.SNt, A.EWTP, B.EWTP, A.name, Имена_ОЭС.nameoes
FROM ([Станции(архив)] AS A INNER JOIN Станции2023 AS B ON (A.Year = B.Year) AND (A.numb1120 = B.numb1120)) INNER JOIN Имена_ОЭС ON A.oes = Имена_ОЭС.oes
WHERE (((A.E)<>[B].[E])) OR (((A.EOTP)<>[B].[EOTP])) OR (((A.EURT)<>[B].[EURT])) OR (((A.EUST)<>[B].[EUST])) OR (((A.Q)<>[B].[Q])) OR (((A.TURT)<>[B].[TURT])) OR (((A.TUST)<>[B].[TUST])) OR (((A.B)<>[B].[B])) OR (((A.GAZ)<>[B].[GAZ])) OR (((A.ISK_GAZ)<>[B].[ISK_GAZ])) OR (((A.MAZUT)<>[B].[MAZUT])) OR (((A.TORF)<>[B].[TORF])) OR (((A.SLAN)<>[B].[SLAN])) OR (((A.PROCH)<>[B].[PROCH])) OR (((A.UGOL)<>[B].[UGOL])) OR (((A.DON)<>[B].[DON])) OR (((A.PODM)<>[B].[PODM])) OR (((A.PECH)<>[B].[PECH])) OR (((A.ARKT)<>[B].[ARKT])) OR (((A.KUZN)<>[B].[KUZN])) OR (((A.URAL)<>[B].[URAL])) OR (((A.BASHK)<>[B].[BASHK])) OR (((A.KAZAH)<>[B].[KAZAH])) OR (((A.KAN)<>[B].[KAN])) OR (((A.TUNG)<>[B].[TUNG])) OR (((A.IRKUT)<>[B].[IRKUT])) OR (((A.HAK)<>[B].[HAK])) OR (((A.TUV)<>[B].[TUV])) OR (((A.BUR)<>[B].[BUR])) OR (((A.CHIT)<>[B].[CHIT])) OR (((A.YAKUT)<>[B].[YAKUT])) OR (((A.AMUR)<>[B].[AMUR])) OR (((A.URG)<>[B].[URG])) OR (((A.USHUM)<>[B].[USHUM])) OR (((A.PRIM)<>[B].[PRIM])) OR (((A.MAG)<>[B].[MAG])) OR (((A.CHUKOT)<>[B].[CHUKOT])) OR (((A.KAMCH)<>[B].[KAMCH])) OR (((A.SAH)<>[B].[SAH])) OR (((A.QOTR)<>[B].[QOTR])) OR (((A.SNK)<>[B].[SNK])) OR (((A.SNt)<>[B].[SNt])) OR (((A.EWTP)<>[B].[EWTP]));
